    12  #define FUZZ_ASSERT(COND)                                                     \
    13          if(!(COND))                                                           \
    14          {                                                                     \
    15            fprintf(stderr, "Assertion failed: " #COND "\n%s",                  \
    16                    strerror(errno));                                           \
    17            assert((COND));                                                     \
    18          }
